from itertools import permutations

# (name, start, end, kind, value); register x starts at 0
H = [("w1", 1, 4, "w", 1),
     ("rA", 2, 5, "r", 1),
     ("rB", 3, 6, "r", 0)]

def legal(order):
    x = 0
    for name, s, e, kind, v in order:
        if kind == "w":
            x = v
        elif v != x:        # a read must return the latest write
            return False
    return True

def real_time_ok(order):
    pos = {op[0]: i for i, op in enumerate(order)}
    for a in H:
        for b in H:
            # a finished before b started: a must come first
            if a[2] < b[1] and pos[a[0]] > pos[b[0]]:
                return False
    return True

for order in permutations(H):
    if real_time_ok(order) and legal(order):
        print([op[0] for op in order])
